const unpaid = [
  { invoice_number: 'INV-2026-001', vendor: 'PT Pertamina Patra Niaga', amount_idr: 75000000, due_date: '2026-11-06', status: 'UNPAID' },
  { invoice_number: 'INV-2026-002', vendor: 'Bengkel Truk Sahabat', amount_idr: 14500000, due_date: '2026-11-10', status: 'WAITING_APPROVAL' }
];

const totalNominal = unpaid.reduce((sum, item) => sum + item.amount_idr, 0);

return JSON.stringify({
  jumlah_tagihan: unpaid.length,
  total_nominal_idr: totalNominal,
  daftar_faktur: unpaid
});

const required = Number($fromAI('required_amount', 'Nominal dana yang dibutuhkan untuk bayar, contoh 75000000') || 0);
const account = ($fromAI('account_name', 'Nama rekening bank, contoh Mandiri Operasional') || 'Mandiri Operasional').trim();

const balances = {
  'Mandiri Operasional': 185000000,
  'BCA Cadangan Pajak': 60000000
};

const currentBalance = balances[account] || 0;
const isEnough = currentBalance >= required;

return JSON.stringify({
  rekening: account,
  saldo_saat_ini: currentBalance,
  dana_dibutuhkan: required,
  apakah_cukup: isEnough,
  sisa_saldo_setelah_bayar: currentBalance - required
});
